class PlaceOrderService:
    def __init__(self, customers, orders, session_factory):
        self._customers, self._orders, self._sf = customers, orders, session_factory

    def place(self, cmd: PlaceOrderCommand) -> OrderId:
        with self._sf.begin() as session:            # one transaction per use case
            customer = self._customers.of_id(session, cmd.customer_id)
            order = customer.place_order(cmd.items)  # the aggregate decides
            self._orders.add(session, order)
            return order.id
